-- Heirloom caches (#7606). The set cache table gave the "Heirloom Cache" (1339058-1339064) the chest and
-- shoulder of its set, which belong to the "Experience Heirloom Cache", and the Experience and full caches
-- (1339051-1339057, 1339065-1339071) were not scripted at all, so they gave nothing. Each cache now holds what
-- its own item description lists ("Contains x3 Heirloom Weapon Token", ...), with the count.
-- Name matches: the description's "Finger of the Sorceror" / "Finger of the Seer" / "Band of the Bulwark" are
-- the Ring of the Sorcerer / Seer / Bulwark, and the Heirloom Cache of Might's "Polished ... of Might" pieces
-- are the Burnished ones its full cache lists.
SET @has_count := (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE()
    AND TABLE_NAME = 'ethereal_bazaar_set_cache' AND COLUMN_NAME = 'count');
SET @add_count := IF(@has_count = 0,
    'ALTER TABLE `ethereal_bazaar_set_cache` ADD COLUMN `count` TINYINT UNSIGNED NOT NULL DEFAULT 1', 'DO 0');
PREPARE add_count FROM @add_count;
EXECUTE add_count;
DEALLOCATE PREPARE add_count;
DELETE FROM `ethereal_bazaar_set_cache` WHERE `cache_item` IN (1339051, 1339052, 1339053, 1339054, 1339055, 1339056, 1339057, 1339058, 1339059, 1339060, 1339061, 1339062, 1339063, 1339064, 1339065, 1339066, 1339067, 1339068, 1339069, 1339070, 1339071);

-- Used, not opened as loot: script, no ITEM_FLAG_HAS_LOOT (0x4), a use spell the client offers.
UPDATE `item_template` SET `ScriptName` = 'item_ethereal_set_cache', `Flags` = `Flags` & ~4
WHERE `entry` IN (1339051, 1339052, 1339053, 1339054, 1339055, 1339056, 1339057, 1339058, 1339059, 1339060, 1339061, 1339062, 1339063, 1339064, 1339065, 1339066, 1339067, 1339068, 1339069, 1339070, 1339071);

-- The Experience Heirloom Caches (weapon tokens, trinkets, chest and shoulder with the experience bonus) are
-- sold at the end of Tiraxis' Heirlooms list, for 800 Bazaar Tokens (ItemExtendedCost 10337).
DELETE FROM `npc_vendor` WHERE `entry` = 900011 AND `item` BETWEEN 1339051 AND 1339057;
